from rcb_client import Robot
import numpy as np, json, os
r=Robot(); o=r.get_obs(video='none'); cur=np.array(o.meta['proprio']['now'][7:14],float); q=np.array([0.,1.,0.,0.])
# all ee pose targets are dense enough to respect 0.25 m/s cap.
P=[]; labels=[]
def seg(a,b,step=.009):
 a=np.array(a,float);b=np.array(b,float);n=max(1,int(np.ceil(np.linalg.norm(b-a)/step)))
 for i in range(1,n+1): P.append(np.r_[a+(b-a)*i/n,q])
def goto(p): seg(cur[:3],p)
# build trajectory from actual current position
here=cur[:3].copy()
def add(p,step=.009):
 global here
 a=here.copy(); b=np.array(p,float); n=max(1,int(np.ceil(np.linalg.norm(b-a)/step)))
 for i in range(1,n+1): P.append(np.r_[a+(b-a)*i/n,q])
 here=b
add([0.,0.,.12]);add([-.10,.15,.12]);add([-.10,.15,.008]);
for _ in range(4):P.append(np.r_[here,q])
add([-.10,.15,.12]);add([-.10,.185,.12]);add([-.12,.185,.12]);add([-.12,.185,.018]);add([-.08,.185,.018]);add([-.08,.185,.12]);
add([-.12,.205,.12]);add([-.12,.205,.010]);add([-.08,.205,.010]);add([-.08,.205,.12])
print('nrows',len(P),'cur',cur.tolist())
for p in [P[0],P[-1],np.r_[[-.1,.15,.008],q],np.r_[[-.1,.185,.018],q]]:
 z=r.ik({'tip':p.tolist()},seed=o.meta['proprio']['now'][:7]); print('IK',z['ok'],z['error'])
res=r.submit('ee_pose',np.array(P),dt=.05,cameras=['practice_cam','side_cam','scene_cam'],video='both',video_fps=10,note='ink dip and practice brush calibration')
print('meta',json.dumps({k:res.meta.get(k) for k in ['plan','clipped','control_steps_chunk','executed_rows','stopped','proprio']},indent=1)[:5000])
print('pose',res.meta['proprio']['now'][7:14]);res.save('/app/output/practice_calibration')
print('status',r.status())
